{
  "restate_the_bet": {
    "one_sentence": "It is a checkpoint that sits in front of an AI coding agent: privileged actions go through one gate that checks who is asking and what they are allowed to do, then acts or refuses."
  },
  "why": {
    "problem": "Give an agent a real task and it runs with your own access — files, git, the network — so it can touch anything you can, and nothing stops it."
  },
  "what": {
    "named": [
      "guest-room",
      "claude-box",
      "prx"
    ],
    "what_one_does": "guest-room is the runtime that scopes an agent: you hand it a named bundle of permissions, and anything outside that bundle fails closed."
  },
  "how_far_along": {
    "working": [
      "Docs generate from source and fail the build on drift",
      "guest-room's behavior specs execute against the engine",
      "Git writes carry signed provenance, tested end to end but opt-in",
      "Contracts stay honest between components"
    ],
    "open_bets": [
      "prx and claude-box converging onto guest-room as one runtime",
      "Keeping components honest with each other as they evolve"
    ],
    "contracts_between_components": "open"
  },
  "who_and_next": {
    "who": "Bobby DeLanghe, one person in Brooklyn, working on it in public and solo.",
    "what_they_want": "He wants to talk to teams chewing on the same problem — the page ends in an email address, not a checkout."
  }
}
